"""Generate unicode_c23_tables.go: the CPython 3.11 Unicode data C23 needs.

    rt --back server/internal/oxidns/unicode_c23_tables.go -- bash -lc \\
        '~/cf-test/.venv/bin/python server/internal/oxidns/testdata/gen_unicode_c23.py'

- alnumRanges: str.isalnum() per character (re's \\w is isalnum or "_").
- encodings.idna's nameprep (stringprep on unicodedata.ucd_3_2_0, with
  str.lower of the running interpreter in map_table_b3): b1 (mapped to
  nothing), b2 (case folding), the prohibited tables C.1.2/C.2.2/C.3–C.9,
  bidi D.1 (RandAL) and D.2 (L).
- NFKC as ucd_3_2_0.normalize computes it: per-character full compatibility
  decomposition (Hangul syllables are algorithmic), combining classes and the
  primary composites of the running interpreter's database.
"""
import os
import stringprep
import sys
import unicodedata
from unicodedata import ucd_3_2_0

MAX = 0x110000
SURROGATES = range(0xD800, 0xE000)


def ranges(pred):
    out, start = [], None
    for cp in range(MAX):
        ok = cp not in SURROGATES and pred(chr(cp))
        if ok and start is None:
            start = cp
        elif not ok and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, MAX - 1))
    return out


def go_ranges(name, items):
    lines = [f'var {name} = [][2]rune{{']
    row = []
    for a, b in items:
        row.append(f'{{0x{a:X}, 0x{b:X}}}')
        if len(row) == 6:
            lines.append('\t' + ', '.join(row) + ',')
            row = []
    if row:
        lines.append('\t' + ', '.join(row) + ',')
    lines.append('}')
    return '\n'.join(lines)


def go_string(s):
    return '"' + ''.join(f'\\U{ord(c):08X}' if ord(c) > 0xFFFF else f'\\u{ord(c):04X}' for c in s) + '"'


def go_map(name, items):
    lines = [f'var {name} = map[rune]string{{']
    for cp, text in items:
        lines.append(f'\t0x{cp:X}: {go_string(text)},')
    lines.append('}')
    return '\n'.join(lines)


def main():
    out = ['// Code generated by testdata/gen_unicode_c23.py; DO NOT EDIT.',
           f'// Python {sys.version.split()[0]}, unicodedata {unicodedata.unidata_version}, stringprep on ucd_3_2_0.',
           '', 'package oxidns', '']
    out.append(go_ranges('alnumRanges', ranges(str.isalnum)))
    out.append(go_ranges('nameprepB1', ranges(stringprep.in_table_b1)))
    b2 = []
    for cp in range(MAX):
        if cp in SURROGATES:
            continue
        c = chr(cp)
        mapped = stringprep.map_table_b2(c)
        if mapped != c:
            b2.append((cp, mapped))
    out.append(go_map('nameprepB2', b2))
    prohibited = (stringprep.in_table_c12, stringprep.in_table_c22, stringprep.in_table_c3,
                  stringprep.in_table_c4, stringprep.in_table_c5, stringprep.in_table_c6,
                  stringprep.in_table_c7, stringprep.in_table_c8, stringprep.in_table_c9)
    out.append(go_ranges('nameprepProhibited', ranges(lambda c: any(f(c) for f in prohibited))))
    out.append(go_ranges('nameprepRandAL', ranges(stringprep.in_table_d1)))
    out.append(go_ranges('nameprepL', ranges(stringprep.in_table_d2)))
    decomp = []
    for cp in range(MAX):
        if cp in SURROGATES or 0xAC00 <= cp <= 0xD7A3:
            continue
        c = chr(cp)
        d = ucd_3_2_0.normalize('NFKD', c)
        if d != c:
            decomp.append((cp, d))
    out.append(go_map('nfkd32', decomp))
    combining = [(cp, unicodedata.combining(chr(cp))) for cp in range(MAX)
                 if cp not in SURROGATES and unicodedata.combining(chr(cp))]
    lines = ['var combiningClass = map[rune]uint8{']
    for cp, value in combining:
        lines.append(f'\t0x{cp:X}: {value},')
    lines.append('}')
    out.append('\n'.join(lines))
    lines = ['var primaryComposites = map[[2]rune]rune{']
    for cp in range(MAX):
        if cp in SURROGATES:
            continue
        d = unicodedata.decomposition(chr(cp))
        if not d or d.startswith('<'):
            continue
        parts = [int(x, 16) for x in d.split()]
        if len(parts) != 2:
            continue
        if unicodedata.normalize('NFC', chr(parts[0]) + chr(parts[1])) == chr(cp):
            lines.append(f'\t{{0x{parts[0]:X}, 0x{parts[1]:X}}}: 0x{cp:X},')
    lines.append('}')
    out.append('\n'.join(lines))
    path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'unicode_c23_tables.go')
    with open(path, 'w') as fh:
        fh.write('\n\n'.join(out) + '\n')
    print('wrote', path, len(b2), len(decomp), len(combining))


if __name__ == '__main__':
    main()
